import{_ as i,o as t,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-09-30 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-09-30 :: Ceph Orchestration Meeting","date":"2019-09-30T00:00:00.000Z","updated":"2019-10-01T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","Bluefs","Rocksdb","OSD","MON","MDS","PG","RADOS","Librados","Libcephfs","Cephfs","Rbd","Radosgw","RGW","RESTful API","认证","授权","加密","纠删码","复制","快照","克隆","虚拟化","云计算","存储","集群","监控"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-09-30_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-09-30_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),r={name:"posts/2019/2019-09-30_-_-_Ceph_Orchestration_Meeting.md"};function s(p,l,n,a,_,g){return t(),e("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年10月（具体日期未提及）</p><p><strong>参会人员</strong>： 多名参与者，包括Ceph研发人员、字幕翻译及总结人员</p><p><strong>会议主题</strong>： 讨论Ceph存储项目中的多个议题，包括远程执行、类型检查、设计文档更新、OSD资源限制、Ceph 1.12版本发布、以及存储卷的发现和库存管理等。</p><p><strong>关键细节与讨论议题</strong>：</p><ol><li><p><strong>远程执行</strong>：</p><ul><li>讨论使用“用户mojo”代替“power-maker”进行远程执行的可能性。</li><li>提及一个开源播客，其中讨论了在本地主机上执行的部分。</li><li>讨论将“安全部署”拆分为“低云部分”和远程执行按钮的必要性。</li></ul></li><li><p><strong>类型检查</strong>：</p><ul><li>提出在Rook模块中实现静态类型检查的需求，以确保API匹配。</li><li>讨论使用Brookes F giant Python库作为临时测试工具。</li><li>认为将此工具集成到Rook项目或Ceph项目中是有益的。</li></ul></li><li><p><strong>设计文档</strong>：</p><ul><li>讨论替换OSD的设计文档，并强调删除和替换OSD实际上是一个连续的过程。</li><li>强调需要对设计文档进行彻底审查。</li></ul></li><li><p><strong>Ceph 1.12版本发布</strong>：</p><ul><li>讨论Ceph 1.12版本的发布计划，包括下一轮修复和更新。</li></ul></li><li><p><strong>OSD资源限制</strong>：</p><ul><li>讨论在升级过程中OSD使用过多内存并导致崩溃的问题。</li><li>认为需要为OSD设置默认的资源限制，以防未指定限制时使用全部内存。</li></ul></li><li><p><strong>存储卷发现和库存管理</strong>：</p><ul><li>讨论使用Safestorage Volume Inventory（SVI）进行存储卷发现和库存管理的可能性。</li><li>讨论将SVI输出传递给编排器，以便生成磁盘组。</li></ul></li></ol><p><strong>决定的事项</strong>：</p><ol><li>将类型检查工具集成到Rook项目或Ceph项目中。</li><li>对设计文档进行最终审查。</li><li>计划Ceph 1.12版本的发布。</li><li>为OSD设置默认资源限制。</li><li>将SVI输出传递给编排器。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li>完成类型检查工具的集成。</li><li>完成设计文档的审查。</li><li>准备Ceph 1.12版本的发布。</li><li>实施OSD资源限制设置。</li><li>实现SVI输出传递给编排器的功能。</li></ol><p><strong>其他事项</strong>：</p><ul><li>讨论了Ceph 1.12版本中OSD升级和崩溃的问题。</li><li>讨论了Ceph集群中与文件系统相关的损坏问题。</li><li>讨论了Ceph集群中与SMB/CIFS文件系统相关的损坏问题。</li><li>讨论了Ceph集群中与RBD镜像相关的损坏问题。</li></ul>',12)])])}const S=i(r,[["render",s]]);export{u as __pageData,S as default};
